public static void lastToFront(Queue<Integer> q) {
    Queue<Integer> temp = new Queue<Integer>();
    int last = 0;
    while (!q.isEmpty()) {
        last = q.remove();
        if (!q.isEmpty()) {
            temp.insert(last);
        }
    }
    q.insert(last);
    while (!temp.isEmpty()) {
        q.insert(temp.remove());
    }
}

public static int removeMin(Queue<Integer> q) {
    Queue<Integer> temp = new Queue<Integer>();
    int min = q.head();
    while (!q.isEmpty()) {
        int x = q.remove();
        if (x < min) {
            min = x;
        }
        temp.insert(x);
    }
    boolean removed = false;
    while (!temp.isEmpty()) {
        int x = temp.remove();
        if (x == min && !removed) {
            removed = true;
        } else {
            q.insert(x);
        }
    }
    return min;
}

