        {
            min = x;
        }
        temp.Insert(x);
    }
    bool removed = false;
    while (!temp.IsEmpty())
    {
        int x = temp.Remove();
        if (x == min && !removed)
        {
            removed = true;
        }
        else
        {
            q.Insert(x);
        }
    }
